  return el('section', { id: 'reuse-section' }, [
    el('h3', { class: 'zh-heading zh-heading--4', text: 'Zitieren und weiterverwenden' }),
    el('p', { class: 'zh-hint', id: 'citation-text', text: citationText(record) }),
    el('div', { class: 'app-detail__actions' }, [
      copyButton,
      record.iiifManifest
        ? el('a', {
