      record.imageService
        ? fullImageLink(record.imageService)
        : el('span', { class: 'zh-hint', text: record.iiifManifest ? 'Weitere Links werden geladen …' : 'Kein IIIF-Bilddienst hinterlegt – nutzen Sie den Originaldatensatz.' }),
