#!/usr/bin/env node
/** Temporary focused check for the shareable viewer region (`vv`). */
import { spawn } from 'node:child_process';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

const BASE = process.argv[2] ?? 'http://127.0.0.1:8787';
const port = 9444;
const userDataDir = await mkdtemp(path.join(tmpdir(), 'cdp-vv-'));
const child = spawn(
  '/usr/bin/chromium',
  ['--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${userDataDir}`, '--no-sandbox', '--disable-gpu', '--window-size=1440,1000', 'about:blank'],
  { stdio: ['ignore', 'ignore', 'pipe'] },
);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function endpoint(p) {
  for (let i = 0; i < 40; i += 1) {
    try {
      const res = await fetch(`http://127.0.0.1:${port}${p}`);
      if (res.ok) return res.json();
    } catch {}
    await sleep(250);
  }
  throw new Error(`CDP ${p} unreachable`);
}
await endpoint('/json/version');
const target = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: 'PUT' }).then((r) => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0;
const pending = new Map();
const events = [];
ws.onmessage = (m) => {
  const d = JSON.parse(m.data);
  if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); }
  else if (d.method) events.push(d);
};
const send = (method, params = {}) => new Promise((res) => { const i = ++id; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
const evaluate = async (expression) => (await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })).result?.result?.value;

await send('Page.enable');
await send('Runtime.enable');
await send('Log.enable');
await send('Network.enable');

const failures = [];
const check = (name, ok, detail = '') => { console.log(`${ok ? '✔' : '✖'} ${name}${detail ? ` — ${detail}` : ''}`); if (!ok) failures.push(name); };

async function goto(url) {
  await send('Page.navigate', { url });
  await sleep(1200);
}
const waitReady = async (ms = 20000) => {
  const started = Date.now();
  while (Date.now() - started < ms) {
    const ready = await evaluate(`(() => {
      const stage = document.querySelector('#viewer-stage');
      const readout = document.querySelector('#viewer-resolution')?.textContent ?? '';
      return stage?.dataset.state === 'ready' && readout && !readout.includes('–') ? readout : null;
    })()`);
    if (ready) return ready;
    await sleep(300);
  }
  return null;
};
const region = async () => evaluate(`(() => {
  const src = document.querySelector('#detail-preview img')?.getAttribute('src') ?? '';
  const m = src.match(/\\/(\\d+,\\d+,\\d+,\\d+|full)\\//);
  return { src: m ? m[1] : src, url: location.search };
})()`);

// 1. deep link, zoom in twice, expect vv in the URL
await goto(`${BASE}/?sel=e-rara:7203621`);
let readout = await waitReady();
check('viewer ready on a deep link', Boolean(readout), readout);
const before = await region();
await evaluate(`document.querySelector('#viewer-zoom-in').click(); document.querySelector('#viewer-zoom-in').click(); true`);
await sleep(2500);
const zoomed = await region();
const zoomedReadout = await evaluate(`document.querySelector('#viewer-resolution').textContent`);
check('zooming writes the region into the URL', /(?:^|&)vv=\d+,\d+,\d+,\d+/.test(zoomed.url), zoomed.url);
check('the zoomed readout names the cut-out', /Ausschnitt/.test(zoomedReadout), zoomedReadout);
check('the image request is a pixel region', /^\d+,\d+,\d+,\d+$/.test(zoomed.src), zoomed.src);

// 2. reload the shared URL -> same region
await goto(`${BASE}/${zoomed.url}`);
const restoredReadout = await waitReady();
const restored = await region();
check('a reloaded permalink restores the same region', restoredReadout === zoomedReadout && restored.src === zoomed.src, `${restoredReadout} | ${restored.src}`);

// 3. "Ganzes Blatt" clears the parameter
await evaluate(`document.querySelector('#viewer-reset').click(); true`);
await sleep(1200);
const reset = await region();
check('“Ganzes Blatt” clears vv from the URL', !/vv=/.test(reset.url) && reset.src === 'full', `${reset.url} | ${reset.src}`);

// 4. hand-edited nonsense is ignored and dropped, viewer still shows the whole sheet
await goto(`${BASE}/?sel=e-rara:7203621&vv=999999,999999,5,5`);
const nonsenseReadout = await waitReady();
const nonsense = await region();
check('an impossible region falls back to the whole sheet', /Gesamtansicht/.test(nonsenseReadout ?? ''), nonsenseReadout);
check('the impossible value is removed from the URL', !/vv=/.test(nonsense.url), nonsense.url);

// 5. a keyboard pan also reaches the URL
await evaluate(`(() => { const s = document.querySelector('#viewer-stage'); s.focus(); s.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true })); return true; })()`);
await sleep(1200);
const panned = await region();
check('keyboard panning is shareable too', /vv=/.test(panned.url), panned.url);

// 6. switching sheets clears the region of the other sheet
await goto(`${BASE}/?sel=e-rara:6485160`);
await waitReady();
await evaluate(`document.querySelector('#viewer-zoom-in').click(); true`);
await sleep(1500);
const sheet1 = await region();
check('sheet 1 of the two-sheet work has a region', /vv=/.test(sheet1.url), sheet1.url);
await evaluate(`document.querySelector('#page-strip [data-sheet="1"]').click(); true`);
await sleep(2000);
const sheet2 = await region();
const sheet2Readout = await evaluate(`document.querySelector('#viewer-resolution').textContent`);
check('switching sheets drops the old region', !/vv=/.test(sheet2.url) && /Gesamtansicht/.test(sheet2Readout), `${sheet2.url} | ${sheet2Readout}`);

// 7. closing the panel leaves no vv behind
await evaluate(`document.querySelector('#detail button[type="button"]').click(); true`);
await sleep(600);
const closed = await region();
check('closing the panel leaves no vv behind', !/vv=/.test(closed.url), closed.url);

const errors = events
  .filter((e) => e.method === 'Runtime.exceptionThrown' || (e.method === 'Log.entryAdded' && e.params.entry.level === 'error'))
  .map((e) => e.params.exceptionDetails?.text ?? e.params.entry?.text);
check('no console errors during the session', errors.length === 0, errors.slice(0, 3).join(' | '));

console.log(failures.length === 0 ? '\nALL PASSED' : `\n${failures.length} FAILED: ${failures.join(', ')}`);
child.kill('SIGKILL');
ws.close();
process.exit(failures.length === 0 ? 0 : 1);

