#!/usr/bin/env node
/** Reproduce the harness sequence: zoom -> pan -> Home -> zoom, watch vv. */
import { spawn } from 'node:child_process';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

const BASE = process.argv[2] ?? 'http://127.0.0.1:8787';
const port = 9455;
const userDataDir = await mkdtemp(path.join(tmpdir(), 'cdp-vv2-'));
const child = spawn('/usr/bin/chromium', ['--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${userDataDir}`, '--no-sandbox', '--disable-gpu', '--window-size=1440,960', 'about:blank'], { stdio: ['ignore', 'ignore', 'pipe'] });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function endpoint(p) {
  for (let i = 0; i < 40; i += 1) {
    try { const r = await fetch(`http://127.0.0.1:${port}${p}`); if (r.ok) return r.json(); } catch {}
    await sleep(250);
  }
  throw new Error('cdp');
}
await endpoint('/json/version');
const target = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: 'PUT' }).then((r) => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map(); const events = [];
ws.onmessage = (m) => { const d = JSON.parse(m.data); if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); } else if (d.method) events.push(d); };
const send = (method, params = {}) => new Promise((res) => { const i = ++id; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
const evaluate = async (e) => (await send('Runtime.evaluate', { expression: e, returnByValue: true, awaitPromise: true })).result?.result?.value;
await send('Page.enable'); await send('Runtime.enable'); await send('Log.enable');
const press = async (key, keyCode) => {
  await send('Input.dispatchKeyEvent', { type: 'keyDown', key, code: key, windowsVirtualKeyCode: keyCode });
  await send('Input.dispatchKeyEvent', { type: 'keyUp', key, code: key, windowsVirtualKeyCode: keyCode });
};
const state = async (tag) => {
  const s = await evaluate(`(() => ({ search: decodeURIComponent(location.search), src: (document.querySelector('.app-viewer__image')?.src || '').slice(-50), readout: document.querySelector('#viewer-resolution')?.textContent || '' }))()`);
  console.log(tag, JSON.stringify(s));
};
const waitRegion = async (ms = 25000) => {
  const t = Date.now();
  while (Date.now() - t < ms) {
    const v = await evaluate(`(() => { const img = document.querySelector('.app-viewer__image'); return { src: img?.src || '', decoded: Boolean(img && img.naturalWidth > 0) }; })()`);
    if (v.decoded && /,\d+\//.test(v.src) && !v.src.includes('/full/')) return v;
    await sleep(250);
  }
  return null;
};
const waitFull = async (ms = 25000) => {
  const t = Date.now();
  while (Date.now() - t < ms) {
    const v = await evaluate(`(() => { const img = document.querySelector('.app-viewer__image'); return { src: img?.src || '', decoded: Boolean(img && img.naturalWidth > 0) }; })()`);
    if (v.decoded && v.src.includes('/full/')) return v;
    await sleep(250);
  }
  return null;
};

await send('Page.navigate', { url: `${BASE}/?sel=e-rara:7203621&to=1850` });
await sleep(1500);
await waitFull();
await state('after load');
await evaluate(`document.querySelector('#viewer-zoom-in').click(); document.querySelector('#viewer-zoom-in').click(); true`);
await waitRegion();
await sleep(800);
await state('after zoom');
await evaluate(`document.querySelector('#viewer-stage').focus()`);
await press('ArrowRight', 39); await press('ArrowRight', 39);
await sleep(900);
await state('after pan');
await press('Home', 36);
await waitFull();
await sleep(900);
await state('after Home');
await evaluate(`document.querySelector('#viewer-zoom-in').click(); document.querySelector('#viewer-zoom-in').click(); true`);
await waitRegion();
await sleep(1200);
await state('after zoom 2');
const errs = events.filter((e) => e.method === 'Runtime.exceptionThrown' || (e.method === 'Log.entryAdded' && e.params.entry.level === 'error')).map((e) => e.params.exceptionDetails?.text ?? e.params.entry?.text);
console.log('console errors:', errs);
child.kill('SIGKILL'); ws.close(); process.exit(0);

