edits.newText:
/* ------------------------------------------------- facts from the manifest */

/**
 * The provider's own metadata rows from the IIIF manifest, verbatim.
 *
 * The harvested record and the manifest overlap (both come from the same
 * METS/OAI record at e-rara), so rows that only repeat what the panel already
 * says in the same words are dropped; everything else is shown as the provider
 * wrote it — physical description, scale, “online since”, shelfmark with the
 * holding library, life dates of the author. Nothing is merged or inferred.
 */
const REPEATED_MANIFEST_LABELS = new Set(['titel', 'title', 'impressum', 'imprint', 'doi', 'permalink', 'urn']);

function manifestSection(record) {
  return el('section', { id: 'manifest-section', hidden: true }, [
    el('h3', { class: 'zh-heading zh-heading--4', text: 'So beschreibt der Anbieter das Werk' }),
    el('dl', { class: 'app-detail__facts', id: 'manifest-facts' }),
    el('p', { class: 'zh-hint', id: 'manifest-note' }),
  ]);
}

/** Fill the manifest block once the manifest is parsed (or hide it). */
function updateManifestSection(record) {
  const section = qs('#manifest-section');
  const list = qs('#manifest-facts');
  const note = qs('#manifest-note');
  if (!section || !list) return;
  const rows = (manifest?.metadata ?? []).filter((row) => !REPEATED_MANIFEST_LABELS.has(String(row.label).trim().toLowerCase()));
  if (rows.length === 0) {
    section.hidden = true;
    list.replaceChildren();
    return;
  }
  list.replaceChildren(...rows.flatMap((row) => [el('dt', { text: row.label }), el('dd', { text: row.value })]));
  if (note) {
    note.textContent = `Wörtlich aus dem IIIF-Manifest des Anbieters (${rows.length} ${rows.length === 1 ? 'Angabe' : 'Angaben'}). Felder, die oben schon stehen, werden hier nicht wiederholt.`;
  }
  section.hidden = false;
}

/* ------------------------------------------------- leading to the series */

manifest = parseManifest(await fetchJson(record.iiifManifest));
renderSheetStrip();
updateManifestSection(record);
showCanvas();

